class LineIntegration : public FELevelSetMoments::LineIntegration {
public:
  static void FullStripMoments(unsigned degree, const FELevelSetMoments::LineIntegrationStrip& strip, long double left, long double right, std::vector<long double>& values, std::vector<long double>& errors, const std::array<long double,5>* coordinates = nullptr, const std::vector<unsigned char>* requested = nullptr);
  static void FastGraphSample(const std::vector<std::vector<long double>>& coefficient, unsigned degree, const FELevelSetMoments::LineIntegrationStrip& strip, long double x, bool computeDelta, bool lowerZero, bool upperZero, std::vector<long double>& values, const std::vector<std::vector<std::vector<long double>>>* surfaceGradient, const std::vector<unsigned char>& active, long double mappedDerivative = -1.0L, const std::array<long double,5>* coordinates = nullptr, int derivativeSign = 0, bool inverseSurface = false, int normalComponent = -1);
  static void IntegrateStrip(const std::vector<std::vector<long double>>& coefficient, unsigned degree, const FELevelSetMoments::LineIntegrationStrip& strip, bool graph, bool mapped, bool computeDelta, long double absoluteH, long double absoluteD, long double relative, unsigned maximumDepth, unsigned maximumEvaluations, unsigned& evaluations, unsigned& accepted, std::vector<long double>& values, std::vector<long double>& errors, const std::vector<std::vector<std::vector<long double>>>* surfaceGradient = nullptr, const std::array<long double,5>* coordinates = nullptr, const std::vector<unsigned char>* requested = nullptr, const FELevelSetMoments::OuterQuadratureRules& rules = FELevelSetMoments::OuterQuadratureRules(), bool inverseSurface = false, int normalComponent = -1);
#ifdef EX47_NATIVE_USE_OLD
  static FELevelSetMoments::LineIntegrationStatistics& Statistics() { return FELevelSetMoments::LineIntegration::Statistics(); }
#else
  static FELevelSetMoments::Ex47Prepared::LineIntegrationStatistics& Statistics() { return FELevelSetMoments::Ex47Prepared::LineIntegration::Statistics(); }
#endif
  static void IntegratePolynomial(long double a, long double b, long double c, unsigned degree, long double left, long double right, bool computeDelta, bool fullBoundaryDelta, std::vector<long double>& positive, std::vector<long double>& delta) { Integrate1DInternal(a,b,c,degree,left,right,computeDelta,fullBoundaryDelta,positive,delta); }
  static bool IntegrateFastGraph(const std::vector<std::vector<long double>>& coefficient, unsigned degree, unsigned order, bool triangle, bool computeDelta, long double derivativeBound, long double absoluteH, long double absoluteDelta, long double relativeTolerance, unsigned maximumDepth, std::vector<long double>& values, std::vector<long double>& errors, unsigned& accepted, const std::vector<std::vector<std::vector<long double>>>* surfaceGradient = nullptr) { return IntegrateCanonicalGraph(coefficient,degree,order,triangle,computeDelta,derivativeBound,absoluteH,absoluteDelta,relativeTolerance,maximumDepth,values,errors,accepted,surfaceGradient); }
};

